            ctx.font = '18px "PingFang SC", sans-serif';
            ctx.fillStyle = 'rgba(255,255,255,0.5)';
            ctx.fillText(p.role, 128, 62);

            const texture = new THREE.CanvasTexture(canvas);
            texture.needsUpdate = true;
            const spriteMat = new THREE.SpriteMaterial({ map: texture, transparent: true, depthTest: false });
            const sprite = new THREE.Sprite(spriteMat);
            sprite.position.set(x, yPos + size + 0.6, z);
            sprite.scale.set(2.5, 0.8, 1);
            personaGroup.add(sprite);

            // 连线到核心
            const lineGeo = new THREE.BufferGeometry().setFromPoints([
                new THREE.Vector3(0, 0, 0),
                new THREE.Vector3(x, yPos, z)
            ]);
            const lineMat = new THREE.LineBasicMaterial({
                color: color,
                transparent: true,
                opacity: 0.15 + 0.15 * health
            });
            const line = new THREE.Line(lineGeo, lineMat);
            personaGroup.add(line);

            personaPositions.push({ x, y: yPos, z, name: p.name });
        });

        scene.add(personaGroup);

        // ---------- 模块层 (半径10，6层架构) ----------
        const moduleGroup = new THREE.Group();
        const layerColors = {
            '协议层': 0xff6b6b,
            '主权层': 0x4facfe,
            '人格层': 0xf0c060,
            '技术层': 0x43e97b,
            '安全层': 0xf9d423,
            '可视化层': 0xa29bfe
        };

        const moduleRadius = 10;
        let moduleIndex = 0;
        DATA.layers.forEach((layer, layerIdx) => {
            const layerAngle = (layerIdx / DATA.layers.length) * Math.PI * 2;
            const layerY = (layerIdx - 2.5) * 1.5;

            layer.modules.forEach((mod, modIdx) => {
                const angle = layerAngle + (modIdx / layer.modules.length) * 1.2 - 0.6;
                const x = Math.cos(angle) * moduleRadius;
                const z = Math.sin(angle) * moduleRadius;

                const size = 0.3 + Math.random() * 0.3;
                const color = layerColors[layer.name] || 0x666666;

                const boxGeo = new THREE.BoxGeometry(size, size, size);
                const boxMat = new THREE.MeshStandardMaterial({
                    color: color,
                    emissive: color,
                    emissiveIntensity: 0.1,
                    metalness: 0.2,
                    roughness: 0.6
                });
                const box = new THREE.Mesh(boxGeo, boxMat);
                box.position.set(x, layerY, z);
                box.userData = { name: mod, layer: layer.name, type: 'module' };
                moduleGroup.add(box);

                // 小连线到最近的3个人格节点 (为了视觉丰富)
                // 简化: 连到最近的3个
                const distances = personaPositions.map((p, i) => ({
                    idx: i,
                    dist: Math.sqrt((p.x - x) ** 2 + (p.y - layerY) ** 2 + (p.z - z) ** 2)
                }));
                distances.sort((a, b) => a.dist - b.dist);
                for (let k = 0; k < Math.min(2, distances.length); k++) {
                    const p = personaPositions[distances[k].idx];
                    const points = [
                        new THREE.Vector3(x, layerY, z),
                        new THREE.Vector3(p.x, p.y, p.z)
                    ];
                    const lineGeo = new THREE.BufferGeometry().setFromPoints(points);
                    const lineMat = new THREE.LineBasicMaterial({
                        color: color,
                        transparent: true,
                        opacity: 0.05
                    });
                    const line = new THREE.Line(lineGeo, lineMat);
                    moduleGroup.add(line);
                }

                moduleIndex++;
            });
        });

        scene.add(moduleGroup);

        // ---------- 决策流 (动态粒子流) ----------
        const flowParticlesGeo = new THREE.BufferGeometry();
        const flowCount = 200;
        const flowPositions = new Float32Array(flowCount * 3);
        const flowSpeeds = new Float32Array(flowCount);
        for (let i = 0; i < flowCount; i++) {
            const angle = Math.random() * Math.PI * 2;
            const radius = 4 + Math.random() * 6;
            flowPositions[i * 3] = Math.cos(angle) * radius;
            flowPositions[i * 3 + 1] = (Math.random() - 0.5) * 8;
            flowPositions[i * 3 + 2] = Math.sin(angle) * radius;
            flowSpeeds[i] = 0.002 + Math.random() * 0.005;
        }
        flowParticlesGeo.setAttribute('position', new THREE.BufferAttribute(flowPositions, 3));
        const flowMat = new THREE.PointsMaterial({
            color: 0xf0c060,
            size: 0.12,
            transparent: true,
            opacity: 0.4,
            blending: THREE.AdditiveBlending
        });
        const flowParticles = new THREE.Points(flowParticlesGeo, flowMat);
        scene.add(flowParticles);

        // ---------- 交互：光线投射 ----------
        const raycaster = new THREE.Raycaster();
        const mouse = new THREE.Vector2();
        let hoveredNode = null;
        let selectedNode = null;
        const nodeInfo = document.getElementById('node-info');

        renderer.domElement.addEventListener('mousemove', (event) => {
            const rect = renderer.domElement.getBoundingClientRect();
            mouse.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
            mouse.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
        });

        renderer.domElement.addEventListener('click', (event) => {
            raycaster.setFromCamera(mouse, camera);

            // 检测人格节点
            const personaMeshes = [];
            personaGroup.children.forEach(child => {
                if (child.isMesh && child.userData.type === 'persona') {
                    personaMeshes.push(child);
                }
            });
            const intersects = raycaster.intersectObjects(personaMeshes);

            if (intersects.length > 0) {
                const node = intersects[0].object;
                const data = node.userData;
                selectedNode = data;
                showNodeInfo(data);
                // 高亮
                node.material.emissiveIntensity = 0.8;
                setTimeout(() => {
                    node.material.emissiveIntensity = 0.15 * (data.health / 100);
                }, 300);
            }
        });

        // ---------- 显示节点信息 ----------
        function showNodeInfo(data) {
            const nameEl = document.getElementById('nodeName');
            const typeEl = document.getElementById('nodeType');
            const statusEl = document.getElementById('nodeStatus');

            nameEl.textContent = data.name;
            typeEl.textContent = `${data.role || '人格'} · ${data.gua || '䷀'}`;
            const health = data.health || 0;
            const color = health >= 80 ? '🟢' : health >= 60 ? '🟡' : '🔴';
            statusEl.textContent = `健康度: ${health}% ${color}`;

            document.getElementById('node-info').classList.add('visible');
        }

        // ---------- 多媒体播放 ----------
        document.querySelectorAll('#node-info .actions button').forEach(btn => {
            btn.addEventListener('click', (e) => {
                const action = e.target.dataset.action;
                const name = document.getElementById('nodeName').textContent;
                if (action === 'video') {
                    openMediaPlayer(name, 'video', 'https://www.w3schools.com/html/mov_bbb.mp4');
                } else if (action === 'audio') {
                    openMediaPlayer(name, 'audio', 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3');
                } else if (action === 'docs') {
                    openMediaPlayer(name, 'docs', '📄 文档内容示例: 这里是 ' + name + ' 的详细文档...');
                } else if (action === 'expand') {
                    alert(`🔍 展开 ${name} 的子层级... (实际将下钻到该人格的关联模块)`);
                }
            });
        });

        function openMediaPlayer(title, type, src) {
            const player = document.getElementById('media-player');
            const container = document.getElementById('mediaContainer');
            const titleEl = document.getElementById('mediaTitle');

            titleEl.textContent = `🎬 ${title} · ${type === 'video' ? '视频' : type === 'audio' ? '音频' : '文档'}`;

            if (type === 'video') {
                container.innerHTML =
                    `<video controls autoplay><source src="${src}" type="video/mp4"></video>`;
            } else if (type === 'audio') {
                container.innerHTML =
                    `<audio controls autoplay><source src="${src}" type="audio/mpeg"></audio>`;
            } else {
                container.innerHTML =
                    `<div style="padding:20px;background:rgba(255,255,255,0.05);border-radius:10px;color:rgba(255,255,255,0.7);font-size:14px;line-height:1.8;">${src}</div>`;
            }

            player.style.display = 'block';
        }

        document.getElementById('mediaClose').addEventListener('click', () => {
            document.getElementById('media-player').style.display = 'none';
            document.getElementById('mediaContainer').innerHTML = '';
        });

        // ---------- 更新DNA ----------
        document.getElementById('hudDna').textContent =
            `🧬 DNA: #龍芯⚡️丙午·丙申·癸亥·午时-3D-TIANYAN-UID9622`;

        // ---------- 动画循环 ----------
        let time = 0;

        function animate() {
            requestAnimationFrame(animate);
            time += 0.01;

            // 核心脉动
            const pulse = 1 + Math.sin(time * 1.5) * 0.03;
            core.scale.set(pulse, pulse, pulse);
            ring.rotation.z += 0.002;
            ring2.rotation.x += 0.001;

            // 人格节点微动
            personaGroup.children.forEach((child, i) => {
                if (child.isMesh && child.userData.type === 'persona') {
                    const offset = i * 0.1;
                    const wave = Math.sin(time * 0.5 + offset) * 0.03;
                    child.position.y += wave * 0.01;
                }
                // 标签 (Sprite) 始终面向相机
                if (child.isSprite) {
                    // Sprite自动面向相机
                }
            });

            // 模块旋转
            moduleGroup.rotation.y += 0.001;

            // 决策粒子流动
            const positions = flowParticles.geometry.attributes.position.array;
            for (let i = 0; i < flowCount; i++) {
                const angle = Math.atan2(positions[i * 3 + 2], positions[i * 3]) + flowSpeeds[i];
                const radius = Math.sqrt(positions[i * 3] ** 2 + positions[i * 3 + 2] ** 2);
                positions[i * 3] = Math.cos(angle) * radius;
                positions[i * 3 + 2] = Math.sin(angle) * radius;
                positions[i * 3 + 1] += Math.sin(time + i) * 0.002;
            }
            flowParticles.geometry.attributes.position.needsUpdate = true;

            // 星空慢转
            stars.rotation.y += 0.0002;
            stars.rotation.x += 0.0001;

            // 更新控件
            controls.update();

            // 光线投射 (悬停检测)
            raycaster.setFromCamera(mouse, camera);
            const allMeshes = [];
            personaGroup.children.forEach(child => {
                if (child.isMesh && child.userData.type === 'persona') {
                    allMeshes.push(child);
                }
            });
            const hits = raycaster.intersectObjects(allMeshes);

            if (hits.length > 0 && hits[0].object !== hoveredNode) {
                hoveredNode = hits[0].object;
                renderer.domElement.style.cursor = 'pointer';
                const data = hoveredNode.userData;
                // 显示悬浮信息 (简化，不覆盖点击详情)
            } else if (hits.length === 0) {
                if (hoveredNode) {
                    hoveredNode = null;
                    renderer.domElement.style.cursor = 'default';
                }
            }

            renderer.render(scene, camera);
        }

        animate();

        // ---------- 自适应 ----------
        window.addEventListener('resize', () => {
            const w = window.innerWidth;
            const h = window.innerHeight;
            camera.aspect = w / h;
            camera.updateProjectionMatrix();
            renderer.setSize(w, h);
        });

        // 加载完成
        document.getElementById('loading-bar').style.width = '100%';
        setTimeout(() => {
            document.getElementById('loading-bar').style.width = '0%';
        }, 500);

        console.log('🐉 龍魂 · 3D天眼宇宙已启动');
        console.log('🧬 DNA: #龍芯⚡️丙午·丙申·癸亥·午时-3D-TIANYAN-UID9622');
        console.log('📊 28人格 · 55模块 · 6层架构 · 实时3D');
    </script>
</body>
</html>
